// Calibration factors (initially set to default values)
float calibration_factor_H = 1.2; // humidity calibration factor
float calibration_factor_T = 0.95; // temperature calibration factor

// DHT library instance
DHT dht(DHT_PIN, DHT_TYPE);

void setup() {
  Serial.begin(9600);
  dht.begin();
}

void loop() {
  // Read temperature and humidity from DHT22 sensor
  float temperature = dht.readTemperature();
  float humidity = dht.readHumidity();

  // Apply calibration factors to the readings
  float calibrated_temperature = temperature * calibration_factor_T;
  float calibrated_humidity = humidity * calibration_factor_H;

  // Print calibrated values to serial monitor
  Serial.print("Temperature (calibrated): ");
  Serial.print(calibrated_temperature);
  Serial.println(" °C");
  Serial.print("Humidity (calibrated): ");
  Serial.print(calibrated_humidity);
  Serial.println(" %");

  delay(2000); // wait 2 seconds before reading again
}
