			width: 100px;
			height: 10px;
			background-color: #666;
			border-radius: 5px;
		}

		.pendulum-bob {
			position: absolute;
			top: 50%;
			left: 50%;
			transform: translate(-50%, -50%);
			border-radius: 50%;
			width: 10px;
			height: 10px;
			background-color: #f00;
		}
	</style>
</head>
<body>
	<div id="pendulum"></div>
	<script>
		let pendulum = {
			rod: document.querySelector('.pendulum-rod'),
			bob: document.querySelector('.pendulum-bob'),
			angle: 0,
			length: 100,
			g: 9.81,
			velocity: 0,
			acceleration: 0
		};

		document.getElementById('release-button').addEventListener('click', () => {
			pendulum.velocity = 0;
			pendulum.angle = parseFloat(document.getElementById('initial-angle').value);
			pendulum.acceleration = -pendulum.g / pendulum.length;
			update();
		});

